exports.description:
Хук связки react-hook-form с RTK Mutation.

Обрабатывает отправку: вызывает мутацию, показывает toast,
проставляет серверные ошибки на поля через `setError`.

@template TFieldValues - Тип полей формы
@template Response - Тип ответа мутации

@param {TUseMutationSubmitPros<TFieldValues, Response>} params
@param {UseMutation} params.useMutation - RTK Mutation hook
@param {Function} [params.onSuccess] - Callback при успехе
@param {Function} [params.onError] - Callback при ошибке
@param {string} [params.targetPrefix] - Префикс для маппинга серверных ошибок на поля формы
@param {boolean} [params.removeEmptyValues=true] - Удалять пустые значения перед отправкой

@returns {{ submit, useMutationReturn }}

@example
const { submit } = useMutationSubmit({
  useMutation: useCreateOrderMutation,
  onSuccess: (data) => navigate(`/orders/${data.data?.uuid}`),
})
return <form onSubmit={submit}>...</form>

exports.propsRaw:
export declare const useMutationSubmit: <TFieldValues extends FieldValues, Response extends TResponse<unknown>>({ onError, onSuccess, removeEmptyValues, targetPrefix, useMutation, }: TUseMutationSubmitPros<TFieldValues, Response>) => {
    submit: (e?: React.BaseSyntheticEvent) => Promise<unknown>;
    useMutationReturn: readonly [(arg: TFieldValues) => import("@reduxjs/toolkit/query").MutationActionCreatorResult<import("@reduxjs/toolkit/query").MutationDefinition<TFieldValues, any, string, Response, string>>, ({
        requestId?: undefined;
        status: import("@reduxjs/toolkit/query").QueryStatus.uninitialized;
        data?: undefined;
        error?: undefined;
        endpointName?: string;
        startedTimeStamp?: undefined;
        fulfilledTimeStamp?: undefined;
    } & {
        status: import("@reduxjs/toolkit/query").QueryStatus.uninitialized;
        isUninitialized: true;
        isLoading: false;
        isSuccess: false;
        isError: false;
    } & {
        originalArgs?: TFieldValues | undefined;
        reset: () => void;
    }) | ({
        status: import("@reduxjs/toolkit/query").QueryStatus.fulfilled;
    } & Omit<{
        requestId: string;
        data?: Response | undefined;
        error?: any;
        endpointName: string;
        startedTimeStamp: number;
        fulfilledTimeStamp?: number;
    }, "data" | "fulfilledTimeStamp"> & Required<Pick<{
        requestId: string;
        data?: Response | undefined;
        error?: any;
        endpointName: string;
        startedTimeStamp: number;
        fulfilledTimeStamp?: number;
    }, "data" | "fulfilledTimeStamp">> & {
        error: undefined;
    } & {
        status: import("@reduxjs/toolkit/query").QueryStatus.fulfilled;
        isUninitialized: false;
        isLoading: false;
        isSuccess: true;
        isError: false;
    } & {
        originalArgs?: TFieldValues | undefined;
        reset: () => void;
    }) | ({
        status: import("@reduxjs/toolkit/query").QueryStatus.pending;
    } & {
        requestId: string;
        data?: Response | undefined;
        error?: any;
        endpointName: string;
        startedTimeStamp: number;
        fulfilledTimeStamp?: number;
    } & {
        data?: undefined;
    } & {
        status: import("@reduxjs/toolkit/query").QueryStatus.pending;
        isUninitialized: false;
        isLoading: true;
        isSuccess: false;
        isError: false;
    } & {
        originalArgs?: TFieldValues | undefined;
        reset: () => void;
    }) | ({
        status: import("@reduxjs/toolkit/query").QueryStatus.rejected;
    } & Omit<{
        requestId: string;
        data?: Response | undefined;
        error?: any;
        endpointName: string;
        startedTimeStamp: number;
        fulfilledTimeStamp?: number;
    }, "error"> & Required<Pick<{
        requestId: string;
        data?: Response | undefined;
        error?: any;
        endpointName: string;
        startedTimeStamp: number;
        fulfilledTimeStamp?: number;
    }, "error">> & {
        status: import("@reduxjs/toolkit/query").QueryStatus.rejected;
        isUninitialized: false;
        isLoading: false;
        isSuccess: false;
        isError: true;
    } & {
        originalArgs?: TFieldValues | undefined;
        reset: () => void;
    })];
};

